1	import * as THREE from 'three';
2	import { generateCity } from './City.js';
3	import { Sun } from './Sun.js';
4	import { Player } from './Player.js';
5	import { Minimap } from './Minimap.js';
6	
7	const GOAL_RADIUS = 3;
8	const UP = new THREE.Vector3(0, 1, 0);
9	
10	/* 마우스 시점 — Pointer Lock으로 커서를 가두고, 마인크래프트처럼 이동량만큼 그대로 시점을 돌린다 */
11	const YAW_SENSITIVITY = 0.0022;   // rad / px
12	const PITCH_SENSITIVITY = 0.0022; // rad / px
13	const PITCH_MIN = 0.15;
14	const PITCH_MAX = 1.15;
15	const DIST_MIN = 4;
16	const DIST_MAX = 20;
17	const ZOOM_SPEED = 0.0016;
18	
19	/* ==========================================================================
20	 *  그림자 도시 — 태양을 피해 그늘만 밟고 목적지에 도달하는 3D 생존 게임.
21	 * ========================================================================== */
22	export class Game {
23	  constructor() {
24	    this.dom = {
25	      container: document.getElementById('game'),
26	      loading: document.getElementById('loading'),
27	      burnVignette: document.getElementById('burnVignette'),
28	      hpFill: document.getElementById('hpFill'),
29	      hpNum: document.getElementById('hpNum'),
30	      statusTag: document.getElementById('statusTag'),
31	      dayFill: document.getElementById('dayFill'),
32	      dayTime: document.getElementById('dayTime'),
33	      goalDist: document.getElementById('goalDist'),
34	      minimapCanvas: document.getElementById('minimap'),
35	      pointerLockOverlay: document.getElementById('pointerLockOverlay'),
36	      endScreen: document.getElementById('endScreen'),
37	      endTitle: document.getElementById('endTitle'),
38	      endSub: document.getElementById('endSub'),
39	      restartBtn: document.getElementById('restartBtn'),
40	    };
41	
42	    this.state = 'playing'; // 'playing' | 'won' | 'lost'
43	    this.keys = new Set();
44	    this.clock = new THREE.Clock();
45	    this.raycaster = new THREE.Raycaster();
46	
47	    this.initScene();
48	    this.initCity();
49	    this.initCamera();
50	    this.initInput();
51	
52	    this.dom.loading.style.display = 'none';
53	    if (import.meta.env.DEV) window.__game = this;
54	    requestAnimationFrame(() => this.loop());
55	  }
56	
57	  initScene() {
58	    this.scene = new THREE.Scene();
59	    this.fog = new THREE.Fog(0x141824, 40, 210);
60	    this.scene.fog = this.fog;
61	
62	    this.renderer = new THREE.WebGLRenderer({ antialias: true });
63	    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
64	    this.renderer.setSize(window.innerWidth, window.innerHeight);
65	    this.renderer.shadowMap.enabled = true;
66	    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
67	    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
68	    this.dom.container.appendChild(this.renderer.domElement);
69	
70	    window.addEventListener('resize', () => this.onResize());
71	  }
72	
73	  initCity() {
74	    this.city = generateCity(this.scene);
75	    this.fog.far = this.city.extent * 1.1;
76	    this.sun = new Sun(this.scene, this.city.extent);
77	    this.player = new Player(this.scene, this.city.spawn);
78	    this.buildGoalBeacon();
79	    this.minimap = new Minimap(this.dom.minimapCanvas, this.city);
80	  }
81	
82	  buildGoalBeacon() {
83	    const g = this.city.goal;
84	    const group = new THREE.Group();
85	    group.position.set(g.x, 0, g.z);
86	
87	    const pillar = new THREE.Mesh(
88	      new THREE.CylinderGeometry(0.3, 0.3, 6, 12),
89	      new THREE.MeshStandardMaterial({ color: 0xd9a441, emissive: 0xd9a441, emissiveIntensity: 0.8, roughness: 0.4 }),
90	    );
91	    pillar.position.y = 3;
92	    group.add(pillar);
93	
94	    const ring = new THREE.Mesh(
95	      new THREE.TorusGeometry(1.4, 0.08, 8, 32),
96	      new THREE.MeshStandardMaterial({ color: 0xffd280, emissive: 0xffd280, emissiveIntensity: 1 }),
97	    );
98	    ring.rotation.x = Math.PI / 2;
99	    ring.position.y = 0.4;
100	    group.add(ring);
101	    this.goalRing = ring;
102	
103	    const light = new THREE.PointLight(0xffcf6b, 2.2, 18, 2);
104	    light.position.y = 3;
105	    group.add(light);
106	
107	    this.scene.add(group);
108	  }
109	
110	  initCamera() {
111	    this.camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 400);
112	    const s = this.city.spawn;
113	
114	    // 스폰 지점에서 도시 중심(목적지 방향)을 바라보도록 초기 시점을 잡는다
115	    const intoCity = new THREE.Vector3(-s.x, 0, -s.z).normalize();
116	    this.camYaw = Math.atan2(intoCity.x, intoCity.z);
117	    this.camPitch = 0.58;
118	    this.camDist = 12;
119	    this.camTarget = new THREE.Vector3(s.x, 1.2, s.z);
120	
121	    this.updateCameraTransform();
122	  }
123	
124	  initInput() {
125	    window.addEventListener('keydown', (e) => {
126	      this.keys.add(e.key.toLowerCase());
127	      if (e.key.toLowerCase() === 'r' && this.state !== 'playing') this.restart();
128	    });
129	    window.addEventListener('keyup', (e) => this.keys.delete(e.key.toLowerCase()));
130	    this.dom.restartBtn.addEventListener('click', () => this.restart());
131	
132	    // 마우스 시점 — 클릭해서 포인터를 잠그면, 이후 마우스 이동량만큼 시점이 그대로 회전한다 (마인크래프트 방식)
133	    const canvas = this.renderer.domElement;
134	    this.pointerLocked = false;
135	
136	    const requestLock = () => {
137	      if (this.state === 'playing') canvas.requestPointerLock();
138	    };
139	    canvas.addEventListener('click', requestLock);
140	    this.dom.pointerLockOverlay.addEventListener('click', requestLock);
141	
142	    document.addEventListener('pointerlockchange', () => {
143	      this.pointerLocked = document.pointerLockElement === canvas;
144	      this.dom.pointerLockOverlay.classList.toggle('show', !this.pointerLocked && this.state === 'playing');
145	    });
146	
147	    document.addEventListener('mousemove', (e) => {
148	      if (!this.pointerLocked) return;
149	      this.camYaw -= e.movementX * YAW_SENSITIVITY;
150	      this.camPitch = THREE.MathUtils.clamp(
151	        this.camPitch + e.movementY * PITCH_SENSITIVITY,
152	        PITCH_MIN, PITCH_MAX,
153	      );
154	    });
155	
156	    canvas.addEventListener('wheel', (e) => {
157	      e.preventDefault();
158	      this.camDist = THREE.MathUtils.clamp(this.camDist + e.deltaY * ZOOM_SPEED * this.camDist, DIST_MIN, DIST_MAX);
159	    }, { passive: false });
160	    canvas.addEventListener('contextmenu', (e) => e.preventDefault());
161	
162	    this.dom.pointerLockOverlay.classList.add('show');
163	  }
164	
165	  updateCameraTransform() {
166	    const horiz = this.camDist * Math.cos(this.camPitch);
167	    const height = this.camDist * Math.sin(this.camPitch);
168	    this.camera.position.set(
169	      this.camTarget.x - Math.sin(this.camYaw) * horiz,
170	      this.camTarget.y + height,
171	      this.camTarget.z - Math.cos(this.camYaw) * horiz,
172	    );
173	    this.camera.lookAt(this.camTarget);
174	  }
175	
176	  restart() { window.location.reload(); }
177	
178	  onResize() {
179	    this.camera.aspect = window.innerWidth / window.innerHeight;
180	    this.camera.updateProjectionMatrix();
181	    this.renderer.setSize(window.innerWidth, window.innerHeight);
182	  }
183	
184	  /** 카메라 시점 기준 WASD 이동 벡터 (XZ 평면) */
185	  computeMoveDir() {
186	    const forward = new THREE.Vector3(Math.sin(this.camYaw), 0, Math.cos(this.camYaw));
187	    const right = new THREE.Vector3().crossVectors(forward, UP).normalize();
188	
189	    const dir = new THREE.Vector3();
190	    const k = this.keys;
191	    if (k.has('w') || k.has('arrowup')) dir.add(forward);
192	    if (k.has('s') || k.has('arrowdown')) dir.sub(forward);
193	    if (k.has('d') || k.has('arrowright')) dir.add(right);
194	    if (k.has('a') || k.has('arrowleft')) dir.sub(right);
195	    if (dir.lengthSq() > 1e-6) dir.normalize();
196	    return dir;
197	  }
198	
199	  /** 플레이어가 태양을 향해 가려진 것 없이 노출돼 있는지 검사 */
200	  computeShadeStatus() {
201	    if (!this.sun.isDaytime) return 'night';
202	    const origin = new THREE.Vector3(this.player.position.x, 1.0, this.player.position.z);
203	    this.raycaster.set(origin, this.sun.direction);
204	    this.raycaster.far = this.city.extent * 1.5;
205	    const hits = this.raycaster.intersectObjects(this.city.occluders, false);
206	    return hits.length > 0 ? 'shade' : 'sun';
207	  }
208	
209	  loop() {
210	    requestAnimationFrame(() => this.loop());
211	    const dt = Math.min(this.clock.getDelta(), 0.1);
212	
213	    if (this.state === 'playing') {
214	      this.sun.update(dt, this.scene, this.fog);
215	
216	      const moveDir = this.computeMoveDir();
217	      this.player.update(moveDir, dt, this.city.collisionBoxes, this.city.half);
218	
219	      const status = this.computeShadeStatus();
220	      this.player.applyEnvironment(status, dt);
221	
222	      this.goalRing.rotation.z += dt * 0.6;
223	
224	      this.camTarget.set(this.player.position.x, 1.2, this.player.position.z);
225	
226	      this.checkOutcome();
227	    }
228	
229	    this.updateCameraTransform();
230	    this.renderer.render(this.scene, this.camera);
231	    this.updateHud();
232	  }
233	
234	  checkOutcome() {
235	    if (!this.player.alive) {
236	      this.finish('lost', '타 버렸습니다', '그늘을 더 자주 이용해 체력을 지키세요.');
237	      return;
238	    }
239	    const dx = this.player.position.x - this.city.goal.x;
240	    const dz = this.player.position.z - this.city.goal.z;
241	    if (Math.hypot(dx, dz) < GOAL_RADIUS) {
242	      this.finish('won', '목적지 도착', '그림자만 밟고 무사히 도착했습니다.');
243	    }
244	  }
245	
246	  finish(state, title, sub) {
247	    this.state = state;
248	    if (document.pointerLockElement) document.exitPointerLock();
249	    this.dom.pointerLockOverlay.classList.remove('show');
250	    this.dom.endScreen.classList.add('show');
251	    this.dom.endTitle.textContent = title;
252	    this.dom.endTitle.className = state === 'won' ? 'win' : 'lose';
253	    this.dom.endSub.textContent = sub;
254	  }
255	
256	  updateHud() {
257	    const p = this.player;
258	    const hpPct = Math.round((p.hp / p.maxHp) * 100);
259	    this.dom.hpFill.style.width = `${hpPct}%`;
260	    this.dom.hpFill.classList.toggle('low', hpPct <= 30);
261	    this.dom.hpNum.textContent = Math.round(p.hp);
262	
263	    const tag = this.dom.statusTag;
264	    const labels = { sun: '☀ 태양 노출 — 화상 중', shade: '⛅ 그늘 — 안전', night: '🌙 밤 — 안전' };
265	    tag.textContent = labels[p.status];
266	    tag.className = p.status;
267	
268	    this.dom.burnVignette.classList.toggle('on', p.burning);
269	
270	    const t = this.sun.progress;
271	    this.dom.dayFill.style.width = `${t * 100}%`;
272	    // t=0 일출(06:00), t=0.25 정오(12:00), t=0.5 일몰(18:00), t=0.75 자정(00:00)
273	    const clock = (t + 0.25) % 1;
274	    const hours = Math.floor(clock * 24);
275	    const mins = Math.floor((clock * 24 * 60) % 60);
276	    this.dom.dayTime.textContent = `${String(hours).padStart(2, '0')}:${String(mins).padStart(2, '0')}`;
