const JUMP_SPEED = 7.2, GRAVITY = 20, dt = 1/60;
let height = 0, velocityY = 0, grounded = true;
let jumpPressed = true;
let maxHeight = 0, frames = 0, landedAt = null;
for (let i = 0; i < 300; i++) {
  if (jumpPressed && grounded) { velocityY = JUMP_SPEED; grounded = false; jumpPressed = false; }
  velocityY -= GRAVITY * dt;
  height += velocityY * dt;
  if (height <= 0) { height = 0; velocityY = 0; if (!grounded) landedAt = i; grounded = true; }
  maxHeight = Math.max(maxHeight, height);
  frames++;
  if (landedAt !== null && i > landedAt) break;
}
console.log("peak height:", maxHeight.toFixed(3), "m, landed at frame", landedAt, `(${(landedAt/60).toFixed(2)}s)`);
'

